import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.Ba39LDvt.js";const p=JSON.parse('{"title":"升学与就业","description":"比较推免直博、境外申请、考研和就业，结合上科大培养项目规划自己的成长路线。","frontmatter":{"title":"升学与就业","description":"比较推免直博、境外申请、考研和就业，结合上科大培养项目规划自己的成长路线。"},"headers":[],"relativePath":"career/index.md","filePath":"career/index.md","lastUpdated":1795525517000}'),h={name:"career/index.md"};function d(o,t,n,s,c,l){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="升学与就业" tabindex="-1">升学与就业 <a class="header-anchor" href="#升学与就业" aria-label="Permalink to &quot;升学与就业&quot;">​</a></h1><p>IC 没有唯一正确的毕业去向。选择的关键不是“哪条路最体面”，而是你希望做什么工作、需要怎样的训练，以及能承担多长时间和多大成本的不确定性。先了解<a href="/shanghaitech-ic-wiki-dev.github.io/research/">科研方向</a>和<a href="/shanghaitech-ic-wiki-dev.github.io/career/jobs">岗位图谱</a>，再反推课程、项目与申请准备。</p><h2 id="四类路径怎么比较" tabindex="-1">四类路径怎么比较 <a class="header-anchor" href="#四类路径怎么比较" aria-label="Permalink to &quot;四类路径怎么比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>适合重点考虑的情形</th><th>要提前准备什么</th><th>进一步阅读</th></tr></thead><tbody><tr><td>推免硕士 / 直博</td><td>具备推免资格，希望继续研究或深化工程训练</td><td>课程基础、科研与项目证据、导师和培养方式匹配</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/career/baoyan">推免指南</a></td></tr><tr><td>境外 PhD / MS</td><td>希望参与国际学术训练，能处理语言、资金与跨文化适应</td><td>研究方向、推荐信、语言成绩、申请材料和预算</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/career/abroad">境外申请</a></td></tr><tr><td>硕士统考</td><td>希望通过统一考试进入目标专业</td><td>招生目录、数学英语、专业课、复试与时间管理</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/career/kaoyan">考研指南</a></td></tr><tr><td>本科 / 研究生就业</td><td>希望进入产业，能用项目证明岗位能力</td><td>技能栈、实习、简历、面试、劳动合同核对</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/career/internship">实习</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/career/jobs">就业</a></td></tr></tbody></table><p>这些路径可以在准备早期共享基础，但不能无限并行。确认录取、签约或接受资助前，应读清相应规则和承诺，不把“先占位置再说”当策略。</p><h2 id="上科大同学需要关注的区别" tabindex="-1">上科大同学需要关注的区别 <a class="header-anchor" href="#上科大同学需要关注的区别" aria-label="Permalink to &quot;上科大同学需要关注的区别&quot;">​</a></h2><p><strong>本校推免与直博。</strong> 信息学院接收 2027 级推免生通知列出了学术型与专业型招生通道，部分专业含直博。直博不是“硕士的自动升级”：需要确认研究兴趣、长期指导关系与培养要求。该年度学术学位直博还涉及导师推荐和师生互选协议；具体资格与步骤见当年通知。</p><p><strong>上海创芯学院联合培养。</strong> 2027 级联合推免通知明确，联合招生授予上海科技大学电子信息（0854）专业学位；它与信息学院常规招生在报名入口、导师选择和培养安排上有区别。不要把不同项目的学制、申请方式与学位要求混用。详见<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">培养项目</a>。</p><p><strong>方向不只等于专业名称。</strong> 同一研究主题可能分布在电子科学与技术、计算机科学与技术或电子信息专业中。反过来，同一专业名称下也可能有差异很大的课题。看导师近期工作、课程、资源和毕业要求，比只看招生代码更重要。</p><h2 id="按阶段安排-而不是被截止日期推着走" tabindex="-1">按阶段安排，而不是被截止日期推着走 <a class="header-anchor" href="#按阶段安排-而不是被截止日期推着走" aria-label="Permalink to &quot;按阶段安排，而不是被截止日期推着走&quot;">​</a></h2><ul><li><strong>探索阶段</strong>：学好数学、编程、电路与器件基础，完成一个能独立解释的项目；接触科研或企业讲座，验证兴趣。</li><li><strong>聚焦阶段</strong>：选择主方向，整理项目记录，了解导师或岗位，积累持续合作形成的推荐与反馈。</li><li><strong>申请阶段</strong>：建立截止日期表，标记材料、联系人、状态和承诺；给考试、面试和修改材料留缓冲。</li><li><strong>决策阶段</strong>：比较培养内容、指导方式、成本、地点、资源和退出规则，不只看名气。所有重要约定尽量以正式文件为准。</li></ul><p>直接就业并不意味着停止学习，读博也不意味着只能做学术。优先建立可迁移能力：分析问题、设计实验、写清文档、与人协作，并对自己提交的结果负责。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎学长学姐通过<a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a>分享升学与就业经验，注明申请 / 招聘年份和方向，删除个人身份信息，不以单个案例代表录取概率或普遍待遇。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2026/0731/c7339a1126058/page.htm" target="_blank" rel="noreferrer">信息学院接收 2027 级推免生通知</a></li><li><a href="https://sist.shanghaitech.edu.cn/2026/0815/c2863a1126312/page.htm" target="_blank" rel="noreferrer">上海创芯学院与上海科技大学接收 2027 级推免生通知</a></li><li><a href="https://yanzhao.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上海科技大学研究生招生网</a></li></ul>',15)])])}const b=a(h,[["render",d]]);export{p as __pageData,b as default};
